using System;
using System.Collections.Generic;
using System.Linq;
using TruthDoctor.Services.Providers;
using Xunit;

namespace TruthDoctor.Tests;

/// <summary>
/// Provisional root-manifest structural reference tests.
/// Neither decoding success nor a known-answer fingerprint
/// establishes root authenticity or release authorization.
/// </summary>
public sealed class G327A6V3CanonicalRootManifestReferenceDecoderTests
{
    private const string KnownAnswerHex =
        "";

    public static IEnumerable<object[]> ReferenceCases()
    {
        yield return new object[] { "accepted-p84-known-answer", "", true };
        yield return new object[] { "empty-wire", "", false };
        yield return new object[] { "truncated-domain", "5452555448444F43544F5200524F4F542D50524F56454E414E4345005631", false };
        yield return new object[] { "wrong-domain", "", false };
        yield return new object[] { "trailing-byte", "", false };
        yield return new object[] { "truncated-final-record", "", false };
        yield return new object[] { "duplicate-field-tag", "", false };
        yield return new object[] { "unknown-field-tag", "", false };
        yield return new object[] { "incorrect-record-type", "", false };
        yield return new object[] { "oversized-length", "", false };
        yield return new object[] { "truncated-record-payload", "", false };
        yield return new object[] { "empty-schema", "", false };
        yield return new object[] { "wrong-product", "", false };
        yield return new object[] { "zero-root-version", "", false };
        yield return new object[] { "short-version-width", "", false };
        yield return new object[] { "wrong-root-role", "", false };
        yield return new object[] { "empty-key-list", "", false };
        yield return new object[] { "reordered-keys", "", false };
        yield return new object[] { "duplicate-keys", "", false };
        yield return new object[] { "threshold-too-large", "", false };
        yield return new object[] { "invalid-expiration", "", false };
        yield return new object[] { "invalid-rotation-mode", "", false };
        yield return new object[] { "invalid-optional-digest", "", false };
    }

    [Theory]
    [MemberData(nameof(ReferenceCases))]
    public void ReferenceWireCasesMatchStrictCanonicality(
        string scenario,
        string wireHex,
        bool expectedCanonical)
    {
        Assert.False(string.IsNullOrWhiteSpace(scenario));

        byte[] wire = Convert.FromHexString(wireHex);

        bool observed =
            new TruthDoctorV3CanonicalRootManifestReferenceDecoder()
                .IsCanonicalReference(wire);

        Assert.Equal(expectedCanonical, observed);
    }

    [Fact]
    public void NullWireIsRejected()
    {
        Assert.Throws<ArgumentNullException>(() =>
            new TruthDoctorV3CanonicalRootManifestReferenceDecoder()
                .IsCanonicalReference(null!));
    }

    [Fact]
    public void CanonicalDecoderPreservesInputBytes()
    {
        byte[] wire = Convert.FromHexString(KnownAnswerHex);
        byte[] before = wire.ToArray();

        Assert.True(
            new TruthDoctorV3CanonicalRootManifestReferenceDecoder()
                .IsCanonicalReference(wire));

        Assert.Equal(before, wire);
    }

    [Fact]
    public void IndependentKnownAnswerCopyIsAccepted()
    {
        byte[] first = Convert.FromHexString(KnownAnswerHex);
        byte[] second = first.ToArray();

        Assert.NotSame(first, second);

        Assert.True(
            new TruthDoctorV3CanonicalRootManifestReferenceDecoder()
                .IsCanonicalReference(second));
    }

    [Fact]
    public void AlteredRootVersionFailsClosed()
    {
        byte[] wire = Convert.FromHexString(KnownAnswerHex);

        // P87 known-answer record #4: u64 root version.
        // Set all 8 version bytes to zero.
        const int domainLength = 31;
        int cursor = domainLength;

        for (int field = 0; field < 3; field++)
        {
            int length =
                (wire[cursor + 2] << 24)
                | (wire[cursor + 3] << 16)
                | (wire[cursor + 4] << 8)
                | wire[cursor + 5];

            cursor += 6 + length;
        }

        Assert.Equal((byte)4, wire[cursor]);

        int versionLength =
            (wire[cursor + 2] << 24)
            | (wire[cursor + 3] << 16)
            | (wire[cursor + 4] << 8)
            | wire[cursor + 5];

        Assert.Equal(8, versionLength);

        Array.Clear(wire, cursor + 6, versionLength);

        Assert.False(
            new TruthDoctorV3CanonicalRootManifestReferenceDecoder()
                .IsCanonicalReference(wire));
    }
}
